const CACHE='leonida-fieldnotes-b546fa6f53066099';
const CORE=['./','index.html','styles.css','app.js','premium.js','vendor/maplibre-gl.js','vendor/maplibre-gl.css','vendor/glyphs/Noto%20Sans%20Regular/0-255.pbf','vendor/glyphs/Noto%20Sans%20Bold/0-255.pbf','assets/fieldnotes.svg','manifest.webmanifest','data/community.json','data/guides.json','data/map-config.json','data/premium-codes.json'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(CORE);const config=await(await fetch('data/map-config.json')).json();await cache.addAll(config.tileManifest.map(x=>typeof x==='string'?x:x.path));const dayTiles=config?.bases?.fieldnotes?.day?.manifest;if(Array.isArray(dayTiles)&&dayTiles.length)await cache.addAll(dayTiles.map(x=>typeof x==='string'?x:x.path));await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('leonida-fieldnotes-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const stored=await cache.match(event.request);if(stored)return stored;const response=await fetch(event.request);if(response.ok&&response.type==='basic')await cache.put(event.request,response.clone());return response;})());});
